param([Parameter(Mandatory = $true)][string]$Key, [string]$Src = "..\final", [string]$Out = "..\photo2")
# Photoreal pass v2: image 1 = Blender render (composition & geometry master), image 2 = developer's official visualization (materials/style)
$ErrorActionPreference = "Stop"
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$refs = Join-Path $here "refs"   # official visualizations from dogma.ru (galleryData on project pages), converted to JPG

$EXT = "Image 1 is my Blender 3D render of a residential complex by the developer DOGMA in Krasnodar, Russia. Image 2 is the developer's official visualization of the SAME complex. " +
  "Create a photorealistic architectural visualization that keeps Image 1 as the master: EXACTLY the same camera position, angle, lens and framing, the same buildings in the same places with the same footprints, heights, floor counts, rooflines and window grid. " +
  "Take the facade materials, colours and fine details from Image 2 so the buildings look exactly like the real project. Do not copy the composition of Image 2. " +
  "Replace the simplified 3D trees, lawns, cars and background blocks with realistic ones: mature and young deciduous trees with natural foliage, manicured lawns, paving, parked cars, street lamps, a few pedestrians, a hazy southern Russian city in the background. " +
  "Realistic daylight, soft natural shadows, subtle reflections in the windows with some curtains and interior lights visible. Professional real-estate visualization quality. No text, no logos, no watermark. Wide 16:9 landscape image."
$INT = "Image 1 is my Blender 3D render of a room in a new business-class apartment in Krasnodar, Russia (ceiling height 2.8 m, 12th floor, view of a green city district through the windows). " +
  "Turn it into a photorealistic professional real-estate interior photograph. Keep EXACTLY the same camera position, wide-angle lens, perspective and framing; the same room geometry, wall, window and door positions and proportions; every object in the same place and of the same size. " +
  "Replace simplified geometry and procedural materials with real ones and add realistic small details (texture of materials, joints, soft shadows, light falloff, reflections), but do not add or remove furniture or change the layout. " +
  "Natural daylight from the windows mixed with warm artificial light, correct white balance, bright and inviting exposure. No people, no text, no logos, no watermark. Wide 16:9 landscape image. "
$C = @{
  rekord   = "Project 'Rekord 2': towers of bright terracotta orange-red clinker brick with graphite-black aluminium window frames; multi-storey vertical bands of stained-glass glazing in black frames; glazed chamfered corner bay windows with dark metal floor bands; French balconies with black bar railings; protruding balconies with black railings at the section ends; dark metal cornices and brick rooftop superstructures with dark caps; light stone ground floor with large shop windows. A red-brick orthodox church with green domes and a school with a stadium are nearby; a railway with a red-white commuter train runs behind."
  samolet7 = "Project 'Samolet 7': towers of dark graphite clinker brick with slim champagne-gold metal frames forming double-height portals around the windows, gold spandrel panels on glazed bay windows, small French balconies with gold railings, a glazed crown with gold fins and a gold cornice; double-height ground floor with gold portals and large shop windows. Mid-rise blocks in light grey-beige brick with bronze-brown panels under the windows and small balconies, and white blocks with orange loggia frames. Courtyards with light paving, turquoise playgrounds, lawns and a small landscaped stream."
  reed     = "Project 'REEDS': towers clad in different brick colours - deep burgundy, dark graphite, sand beige, rust red, warm brown, taupe - with brick pilasters every two window bays rising above the roof, recessed loggias with black railings and string courses; mid-rise blocks in textured brown and beige brick with horizontal bands every two floors and French balconies with black railings; a double-height light limestone podium with tall dark windows. Riverside location on the Kuban river with reeds and a park; courtyards with stone paths, boulders, flower beds and playgrounds."
  park3    = "Project 'Park Pobedy 3': a closed urban block - two 21-storey towers whose lower floors are dark chocolate-brown brick and light grey mottled brick with small balconies with black railings, a white band and a 4-storey crown of beige-bronze pilasters with full-height glazing topped with a large projecting bronze frame cornice; 12-13-storey connecting wings alternating light grey brick and dark brown brick sections with small balconies; a dark double-height ground floor with stone pilasters and tall shop windows; an enclosed garden courtyard with a white tensile canopy arch, flowering trees and a blue playground."
}
$ROUGH = "Finish level ROUGH (shell & core): walls of grey gypsum plaster with slight unevenness, floor of flat grey cement screed, bare concrete ceiling, single bare light bulbs on black cords, empty electrical boxes, white PVC windows without sills, white sectional radiators, interior door openings without doors (but the steel front entrance door is installed and closed), water and sewer risers with valves and meters in the bathroom, bitumen waterproofing on the bathroom floor. Completely empty and broom-clean."
$DEV = "Finish level WHITE BOX from the developer: smooth warm off-white painted walls, light natural-oak laminate floor, white skirting, white interior doors with chrome handles and casings, white window sills, white radiators, white sockets and switches, simple round ceiling lights; bathroom with light grey large-format wall and floor tiles, white bathtub with chrome mixer, white toilet, white washbasin with cabinet and mirror, chrome heated towel rail. No furniture."
$TURN = "Finish level TURNKEY designer renovation: oak herringbone parquet, warm white Venetian plaster walls with a greige accent wall, recessed ceiling spotlights and LED coves, oak interior doors with black handles, linen curtains; built-in handleless white kitchen with marble-look stone worktop and backsplash, induction hob, oven, tall oak column with built-in fridge, oak island with black stools and three linen pendant lamps, grey upholstered sofa with cushions and throw, oak coffee table on a wool rug, wall-mounted TV over an oak media unit, shelves with books, fiddle-leaf fig plant, floor lamp; bedroom with upholstered headboard bed, linen bedding, oak nightstands with lamps, abstract painting, built-in white wardrobe; bathroom in large-format white marble porcelain with walk-in shower, glass partition, black rain shower, wall-hung toilet, oak vanity with vessel basin, LED mirror; hallway with mirrored wardrobe, oak bench and brass hooks."
$ROOM = @{ living = "The room is the kitchen-living room."; bed = "The room is the bedroom."; bath = "The view is into the bathroom through its doorway from the hallway."; hall = "The view is of the entrance hallway: the dark rectangle in the middle of the far wall is the CLOSED steel apartment entrance door (dark grey metal leaf with a handle and peephole, in a metal frame) - keep it a closed door, not an opening." }

if ($Key -match '^apt_(rough|dev|turn)_(living|bed|bath|hall)$') {
  $fin = $Matches[1]; $room = $Matches[2]
  $p = "$INT $($ROOM[$room]) " + @{ rough = $ROUGH; dev = $DEV; turn = $TURN }[$fin]
  $imgs = @((Join-Path $here "$Src\$Key.png"))
} elseif ($Key -match '^(rekord|samolet7|reed|park3)_(aerial|yard|street)$') {
  $cx = $Matches[1]; $view = $Matches[2]
  $refname = @{ rekord = @{ aerial = 'rekord_aerial'; yard = 'rekord_yard'; street = 'rekord_facade' }; samolet7 = @{ aerial = 'samolet_aerial'; yard = 'samolet_yard'; street = 'samolet_facade' };
    reed = @{ aerial = 'reeds_aerial'; yard = 'reeds_yard'; street = 'reeds_street' }; park3 = @{ aerial = 'park3_aerial'; yard = 'park3_yard'; street = 'park3_street' } }[$cx][$view]
  $vdesc = @{ aerial = 'Bird''s-eye view.'; yard = 'Eye-level view inside the car-free landscaped courtyard: make the courtyard lush and lived-in (paths, lawns, flower beds, benches, playground, residents walking).'; street = 'Eye-level street view from the sidewalk.' }[$view]
  $p = "$EXT $($C[$cx]) $vdesc"
  $imgs = @((Join-Path $here "$Src\$Key.png"), (Join-Path $refs "$refname.jpg"))
} else { throw "unknown key $Key" }
foreach ($i in $imgs) { if (-not (Test-Path $i)) { throw "missing $i" } }
& (Join-Path $here "gen_codex.ps1") -Prompt $p -OutDir (Join-Path $here $Out) -Name $Key -Image $imgs
